// Fonts (brief section 2). next/font sets --font-text / --font-hand on <html>; tokens.css builds
// --ff-display / --ff-text / --ff-hand (with fallbacks) from them.
// Fraunces (--font-display) is self-hosted instead (src/styles/fonts.css, generated by
// scripts/fonts.py): every rule on the page uses SOFT 100, so that axis is pinned, which halves the
// files with identical glyphs. Its latin files are preloaded in layout.tsx (fontPreload.ts).
// Non-Latin translation lines (中文, 한국어, हिन्दी) load on demand: see loadTranslationFonts() in
// src/lib/fonts.ts (InTheirWords calls it when the section is within one viewport).
//
// Budget (brief 11): `subsets` only decides what is PRELOADED. Every face still has its latin-ext
// subset behind unicode-range, so "Español", "Italiano", "Phở" and credit names fetch their glyphs
// on demand. Preloaded: Fraunces normal + italic and DM Sans normal, latin only (3 files). DM Sans
// has no italic on the page, so that face isn't shipped.
import { Caveat, DM_Sans } from 'next/font/google';

export const text = DM_Sans({
  subsets: ['latin'],
  style: ['normal'],
  axes: ['opsz'],
  variable: '--font-text',
  display: 'swap',
});

export const hand = Caveat({
  subsets: ['latin'],
  weight: ['600'],
  variable: '--font-hand',
  display: 'swap',
  preload: false,
});

export const fontVariables = `${text.variable} ${hand.variable}`;
